
body.wow-quiet #wowMaster{background-image:url('data:image/png;base64,')!important;background-size:100% 100%!important;background-position:center!important}
body.wow-quiet #wowMaster .hot,body.wow-quiet #wowMaster .master-actions,body.wow-quiet #wowMaster .master-note,body.wow-quiet #wowAutoHosts,body.wow-quiet #wowMasterHeroLinks,body.wow-quiet #wowMasterZoneTargets,body.wow-quiet #wowDirectGis,body.wow-quiet #wowNatkoReplay,body.wow-quiet #tpuPhotoDashboardLink,body.wow-quiet #wow-evidence-open,body.wow-quiet #tpuPresentationControls,body.wow-quiet #tpuGuideDock,body.wow-quiet #teraAvatarDock,body.wow-quiet #v13Flight,body.wow-quiet #tpuUniversalBack,body.wow-quiet #wowBackToMaster{display:none!important;pointer-events:none!important}
#wowQuietHome{display:none;position:absolute;inset:0;z-index:50;pointer-events:none;font-family:Segoe UI,Arial,sans-serif}
body.wow-quiet #wowQuietHome{display:block}
#wowQuietTitle{position:absolute;left:4%;top:4%;margin:0;font-size:clamp(25px,3vw,46px);font-weight:800;color:#103c2b;text-shadow:0 2px 14px #ffffffe0;padding:8px 16px;border-radius:15px;background:#f5fff5ae;backdrop-filter:blur(4px)}
#wowQuietHome .quiet-character{position:absolute;pointer-events:auto;border:0;background:transparent;border-radius:50%;cursor:pointer;padding:0;color:#123d2d}
#wowQuietTera{left:21%;top:23%;width:30%;height:48%}#wowQuietNatu{left:61%;top:44%;width:21%;height:42%}
#wowQuietHome .quiet-character span{position:absolute;left:50%;bottom:-2%;transform:translateX(-50%);font-size:clamp(15px,1.4vw,22px);font-weight:750;background:#f7fff2dd;border:1px solid #fff9;border-radius:999px;padding:6px 18px;box-shadow:0 3px 12px #163e2e30;white-space:nowrap;transition:background .15s}
#wowQuietHome .quiet-character:hover span,#wowQuietHome .quiet-character:focus-visible span{background:#fff;box-shadow:0 0 0 3px #8fcba5a0}
#wowQuietHome .quiet-character:focus-visible{outline:3px solid #fff;outline-offset:5px}
#ntOpen{min-width:46px!important;padding:9px 13px!important;font-size:14px!important;background:#113e2dda!important;box-shadow:0 2px 12px #0002!important}
#ntPanel{max-height:calc(100vh - 90px);overflow:auto;width:min(360px,calc(100vw - 30px))}
#ntPanel .quiet-functions{margin-top:10px;border-top:1px solid #cee2d1;padding-top:9px}
#ntPanel .quiet-functions summary{cursor:pointer;font-size:13px;font-weight:700;padding:3px 0 7px}
#ntPanel .quiet-function-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px}
#ntPanel .quiet-function-grid button,#ntPanel .quiet-function-grid a{display:block;font-size:12px;text-align:left;border:1px solid #7da68d;border-radius:10px;background:#eaffeb;color:#163e2e;padding:7px 8px;text-decoration:none;cursor:pointer;pointer-events:auto}
#ntPanel .quiet-functions [data-quiet-action="classic"]{grid-column:1/-1}
#ntPanel .ntControls{flex-wrap:wrap}#ntPanel #ntCommand{flex-basis:calc(100% - 95px)}
@media(max-width:600px){#wowQuietTitle{left:3%;top:3%;padding:7px 12px}#ntPanel{max-height:68vh}#wowQuietHome .quiet-character span{padding:5px 12px}}
